import app from 'flarum/admin/app';
import { configChain } from '../../common/resolveConfig';

/** A config row target, as the API expects it. */

/** `global`, `discussion`, `tag:12`… to `{ scope, scopeId }`. */
export function targetOf(key) {
  const [scope, scopeId = ''] = key.split(':');
  return {
    scope: scope,
    scopeId
  };
}

/**
 * The keys of the configs a target inherits from, from the most general to
 * the closest. For example `['global', 'tag']` for `tag:12`, or
 * `['global', 'tag', 'tag:3']` when tag 12 is a child of tag 3.
 */
export function parentChain(key, parentId) {
  const {
    scope,
    scopeId
  } = targetOf(key);
  return configChain(scope, scopeId, parentId).slice(0, -1);
}

/** What `tagOrder()` needs to know about a tag. */

/**
 * Tag ids in Flarum's order: primary tags by position, each followed by its
 * children, then secondary tags (no position) by name.
 */
export function tagOrder(tags) {
  const byPosition = (a, b) => (a.position ?? 0) - (b.position ?? 0);
  const roots = tags.filter(tag => !tag.parentId);
  const primary = roots.filter(tag => tag.position !== null).sort(byPosition);
  const secondary = roots.filter(tag => tag.position === null).sort((a, b) => a.name.localeCompare(b.name));
  return [...primary, ...secondary].flatMap(tag => [tag.id, ...tags.filter(child => child.parentId === tag.id).sort(byPosition).map(child => child.id)]);
}

/** Targets with one config per page: the extension and the store type of their pages. */
export const PAGE_TARGETS = {
  pages: {
    extension: 'fof-pages',
    type: 'pages'
  },
  advancedPages: {
    extension: 'tryhackx-advanced-pages',
    type: 'advanced-pages'
  }
};

/** The page of a page target (`pages:3`), if loaded. */
export function targetPage(scope, scopeId) {
  const target = PAGE_TARGETS[scope];
  return target && scopeId ? app.store.getById(target.type, scopeId) : undefined;
}
flarum.reg.add('walsgit-custom-heroes', 'admin/utils/scopes', { targetOf: targetOf,parentChain: parentChain,tagOrder: tagOrder,PAGE_TARGETS: PAGE_TARGETS,targetPage: targetPage, });