import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Select from 'flarum/common/components/Select';
const t = (key, params = {}) => app.translator.trans(`walsgit-custom-heroes.admin.placement.${key}`, params, true);

/** Where buttons or icons go, and what they do on mobile. */
export default class PlacementFields extends Component {
  view() {
    const {
      placement,
      mobile,
      taken,
      noBelowText,
      onchange
    } = this.attrs;
    return [m("div", {
      className: "Form-group"
    }, m("label", null, t('label')), m(Select, {
      value: placement,
      options: Object.fromEntries(['below-text', 'top-left', 'top-right', 'bottom-left', 'bottom-right'].filter(value => !noBelowText || value !== 'below-text').map(value => [value,
      // Below the text can be shared: buttons first, then icons.
      {
        label: t(value.replace('-', '_')),
        disabled: value !== 'below-text' && value === taken
      }])),
      onchange: value => onchange({
        placement: value
      })
    }), m("p", {
      className: "helpText"
    }, t(noBelowText ? 'help_corners' : 'help'))), m("div", {
      className: "Form-group"
    }, m("label", null, t('mobile_label')), m(Select, {
      value: placement === 'below-text' && mobile === 'below-text' ? 'same' : mobile,
      options: {
        same: t('mobile_same'),
        // Already below the text.
        ...(placement === 'below-text' || noBelowText ? {} : {
          'below-text': t('mobile_below_text')
        }),
        hide: t('mobile_hide')
      },
      onchange: value => onchange({
        mobile: value
      })
    }))];
  }
}
flarum.reg.add('walsgit-custom-heroes', 'admin/components/PlacementFields', PlacementFields);